// plugins/lark/src/tools/transparency.ts
function registerTransparencyTools(ctx) {
  const { server, memoryStore, channel, resolveCaller } = ctx;
  server.registerTool(
    "what_do_you_know",
    {
      description: "List what the bot has stored in the caller's profile. Output is filtered by current-chat rendering visibility (path B): in a private chat both public and private tiers are rendered; in a group chat only the public tier \u2014 because the reply is visible to the whole group. Each returned line has a short hash that forget_memory uses to target the exact line.",
      inputSchema: external_exports.object({
        chat_id: external_exports.string().describe("Chat ID where this call is acting from"),
        thread_id: external_exports.string().optional().describe(
          "Thread ID from the current notification's metadata. Required whenever present \u2014 the server resolves caller identity from (chat_id, thread_id); omitting it falls back to chat-level and will silently attribute the call to the wrong user in cronjob turns."
        )
      })
    },
    async ({ chat_id, thread_id }) => {
      const auditArgs = { chat_id, thread_id };
      const auth = resolveCaller("what_do_you_know", chat_id, thread_id, auditArgs);
      if ("error" in auth) return auth.error;
      const { caller } = auth;
      const isPrivate = channel.isPrivateChat(chat_id);
      const pub = await memoryStore.listProfileLines(caller, "public");
      const priv = isPrivate ? await memoryStore.listProfileLines(caller, "private") : [];
      const renderSection = (tier, lines) => lines.length === 0 ? `_${tier}: (empty)_` : `**${tier}:**
${lines.map((l) => `- [${l.hash}] ${l.text}`).join("\n")}`;
      const parts = [renderSection("public", pub)];
      if (isPrivate) parts.push(renderSection("private", priv));
      const footer = isPrivate ? "\n\n_Use `forget_memory(hash, tier)` to remove a line._" : "\n\n_Private tier hidden in this group. Ask in private chat to see both tiers._";
      void audit("what_do_you_know", caller, auditArgs, "ok");
      return {
        content: [
          {
            type: "text",
            text: `What I've stored about you:

${parts.join("\n\n")}${footer}`
          }
        ]
      };
    }
  );
  server.registerTool(
    "forget_memory",
    {
      description: "Remove a specific line from the caller's profile. Always caller-scoped \u2014 you can only forget things about yourself. Optionally promotes the removed line into a persistent L2 rule so future distillations classify similar content as private.",
      inputSchema: external_exports.object({
        chat_id: external_exports.string().describe("Chat ID where this call is acting from"),
        thread_id: external_exports.string().optional().describe(
          "Thread ID from the current notification's metadata. Required whenever present \u2014 the server resolves caller identity from (chat_id, thread_id); omitting it falls back to chat-level and will silently attribute the call to the wrong user in cronjob turns."
        ),
        hash: external_exports.string().describe("Short 8-char line hash obtained from what_do_you_know"),
        tier: external_exports.enum(["public", "private"]).default("public").describe('Which tier the line lives in. Default "public" since that is where misclassifications are externally visible.'),
        promote_to_rule: external_exports.boolean().optional().default(false).describe(
          "If true, also append the removed line's text to privacy-rules.md under '## Always private' so future distillations classify similar content as private. Use when the removal reflects a durable preference ('I never want anything like this public') rather than a one-off cleanup."
        )
      })
    },
    async ({ chat_id, thread_id, hash, tier, promote_to_rule }) => {
      const auditArgs = { chat_id, thread_id, hash, tier, promote_to_rule };
      const auth = resolveCaller("forget_memory", chat_id, thread_id, auditArgs);
      if ("error" in auth) return auth.error;
      const { caller } = auth;
      const lines = await memoryStore.listProfileLines(caller, tier);
      const target = lines.find((l) => l.hash === hash);
      if (!target) {
        return {
          isError: true,
          content: [
            {
              type: "text",
              text: `No line with hash "${hash}" in ${tier} tier. Call what_do_you_know to list current lines.`
            }
          ]
        };
      }
      const removed = await memoryStore.removeProfileLine(caller, tier, hash);
      if (!removed) {
        return {
          isError: true,
          content: [{ type: "text", text: `Failed to remove line "${hash}".` }]
        };
      }
      let tail = "";
      if (promote_to_rule) {
        try {
          const { addL2Rule: addL2Rule2 } = await Promise.resolve().then(() => (init_privacy_rules(), privacy_rules_exports));
          await addL2Rule2(target.text, "Always private");
          tail = ' Also appended to privacy-rules.md under "Always private" \u2014 future distillations will classify similar content accordingly.';
        } catch (err) {
          tail = ` (Warning: removal succeeded but failed to append rule to privacy-rules.md: ${err instanceof Error ? err.message : String(err)}. You can add the rule manually.)`;
        }
      }
      void audit("forget_memory", caller, auditArgs, "ok");
      return {
        content: [
          {
            type: "text",
            text: `Removed "${target.text}" from ${tier} profile.${tail}`
          }
        ]
      };
    }
  );
}

// plugins/lark/src/tools/access-control.ts
init_config();
function textResult(text, isError = false) {
  return {
    ...isError ? { isError: true } : {},
    content: [{ type: "text", text }]
  };
}
function formatSnapshot() {
  return JSON.stringify(accessControlStore.snapshot(), null, 2);
}
function registerAccessControlTools(ctx) {
  ctx.server.registerTool(
    "manage_access_control",
    {
      description: "Owner-only runtime access control management for this Lark bridge. Supports list/add/remove for allowed users, allowed chats, and trusted no-mention chats. Pass chat_id/thread_id from current channel metadata.",
      inputSchema: external_exports.object({
        action: external_exports.enum(["list", "add", "remove"]).default("list"),
        list: external_exports.enum(ACCESS_CONTROL_LISTS).optional(),
        value: external_exports.string().optional(),
        chat_id: external_exports.string().describe("Current channel chat_id for server-side caller resolution"),
        thread_id: external_exports.string().optional().describe("Current channel thread_id for server-side caller resolution")
      })
    },
    async ({ action = "list", list, value, chat_id, thread_id }) => {
      const auditArgs = { action, list, value, chat_id, thread_id };
      const auth = ctx.resolveCaller("manage_access_control", chat_id, thread_id, auditArgs);
      if ("error" in auth) return auth.error;
      const { caller } = auth;
      if (!appConfig.ownerOpenId || caller !== appConfig.ownerOpenId) {
        await audit("manage_access_control", caller, auditArgs, "denied");
        return textResult("manage_access_control is owner-only. Set LARK_OWNER_OPEN_ID and call from that owner identity.", true);
      }
      if (action === "list") {
        await audit("manage_access_control", caller, auditArgs, "ok");
        return textResult(formatSnapshot());
      }
      if (!list) {
        await audit("manage_access_control", caller, auditArgs, "denied");
        return textResult("list is required for add/remove.", true);
      }
      if (!value) {
        await audit("manage_access_control", caller, auditArgs, "denied");
        return textResult("value is required for add/remove.", true);
      }
      try {
        const validated = await validateAccessControlMutation({
          action,
          list,
          value,
          currentChatId: chat_id,
          currentChatType: ctx.channel.isPrivateChat(chat_id) ? "p2p" : "group",
          validateChatAccess: (chatId) => validateFeishuChatAccess(ctx.client, chatId)
        });
        const result = await accessControlStore.mutate({
          action: validated.action,
          list: validated.list,
          value: validated.value,
          updatedBy: caller
        });
        await audit("manage_access_control", caller, auditArgs, "ok");
        return textResult(
          formatAccessControlMutationMessage(
            result.changed,
            validated.action,
            validated.list,
            validated.value
          )
        );
      } catch (err) {
        await audit("manage_access_control", caller, auditArgs, "error");
        return textResult(err instanceof Error ? err.message : String(err), true);
      }
    }
  );
}

// plugins/lark/src/tools.ts
function registerTools(server, client, memoryStore, identitySession, channel, conversationBuffer, ackReactions, botMessageTracker, latestMessageTracker, turnObligations, profileDistiller, larkTransport) {
  const ctx = createToolContext({
    server,
    client,
    memoryStore,
    identitySession,
    channel,
    conversationBuffer,
    ackReactions,
    botMessageTracker,
    latestMessageTracker,
    turnObligations,
    profileDistiller,
    larkTransport
  });
  registerDocCommentTools({
    server,
    transport: ctx.transport,
    identitySession,
    conversationBuffer
  });
  registerLocalCliTools({ server, identitySession });
  registerReplyTools(ctx);
  registerMessageMutationTools(ctx);
  registerMemoryTools(ctx);
  registerJobTools(ctx);
  registerTransparencyTools(ctx);
  registerAccessControlTools(ctx);
}

