// plugins/lark/src/conversation-flush-service.ts
function registerConversationFlushHandler(options) {
  const {
    buffer,
    identitySession,
    profileDistiller,
    chatVisibility,
    getActionDispatcher
  } = options;
  buffer.setFlushHandler(async ({ chatId, threadId, messages, reason }) => {
    const flushPrompt2 = buildFlushPrompt(chatId, messages, threadId);
    console.error(
      `[distiller] ${reason} flush for chat ${chatId}${threadId ? ` thread=${threadId}` : ""}: ${messages.length} messages`
    );
    identitySession.setCaller(chatId, threadId, SYSTEM_FLUSH_CALLER);
    const actionDispatcher = getActionDispatcher();
    if (!actionDispatcher) {
      throw new Error("Codex exec action dispatcher is not configured for conversation flush.");
    }
    let summary = "";
    let saveMemoryOk = false;
    await deliverMessageViaCodexExec({
      message: {
        messageId: `flush-${Date.now()}`,
        chatId,
        ...threadId ? { threadId } : {},
        chatType: "system",
        senderId: "system",
        text: flushPrompt2,
        messageType: "text",
        rawContent: flushPrompt2
      },
      displayLabel: threadId ? `System flush \xB7 ${chatId} \xB7 ${threadId}` : `System flush \xB7 ${chatId}`,
      useCodexSessions: false,
      progressVisible: false,
      actionDispatcher,
      sendReply: async () => ({ sentCount: 0, statusText: "Synthetic flush reply suppressed." }),
      onFinalText: (text) => {
        summary = text.trim();
      },
      onActionResults: (results) => {
        saveMemoryOk = results.some((result) => result.ok && result.action === "save_memory");
      }
    });
    if (!saveMemoryOk) {
      throw new Error("Conversation flush did not persist a memory summary.");
    }
    const activeUserIds = [...new Set(
      messages.filter((message) => message.role === "user").map((message) => message.senderId).filter((senderId) => senderId && senderId !== "system")
    )];
    for (const userId of activeUserIds) {
      void profileDistiller.maybeDispatch({
        userId,
        chatId,
        chatType: chatVisibility.isPrivateChat(chatId) ? "p2p" : "group"
      }).then((result) => {
        if (result.status === "error") {
          console.error(`[profile-distill] dispatch failed for ${userId}: ${result.error ?? "unknown error"}`);
        }
      }).catch((err) => logSafeError("[profile-distill] dispatch failed:", err));
    }
    return { summary };
  });
}

