    const candidateDelta = progress?.delta ?? createAttemptDelta(previous, candidate);
    const delta = rawVerification.status === "accepted" ? candidateDelta : rejectedAttemptDelta(candidateDelta);
    const verification = rawVerification.status === "accepted" && progress?.decision === "recover" ? {
      status: "revision_required",
      findings: ["A continue outcome requires one concrete next action."]
    } : rawVerification;
