      schedule_human: job.scheduleHuman,
      timezone: job.timezone,
      prompt: job.prompt,
      target_chat_id: job.targetChatId,
      origin_chat_id: job.originChatId,
      ...job.model ? { model: job.model } : {},
      status: "active",
      created_by: job.createdBy,
      created_at: job.createdAt
